// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { AppShell } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Layout/AppShell)

figma.connect(AppShell, FIGMA_NODE_URL, {
  props: {
    ambient: figma.boolean('ambient'),
    label: figma.string('label'),
  },
  example: ({ label, ambient }) => (
    <AppShell ambient={ambient}>{label}</AppShell>
  ),
});
